CREATE TABLE IF NOT EXISTS website_pages (
  id CHAR(36) PRIMARY KEY, page_group ENUM('primary','additional') NOT NULL DEFAULT 'primary',
  title VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, menu_label VARCHAR(120), summary TEXT, body LONGTEXT,
  hero_image TEXT, call_to_action_label VARCHAR(120), call_to_action_url TEXT, seo_title VARCHAR(255), seo_description TEXT, reference_url TEXT, reference_image_url TEXT,
  status ENUM('draft','published','archived') NOT NULL DEFAULT 'draft', sort_order INT NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY idx_website_pages_group_status (page_group, status), KEY idx_website_pages_sort (sort_order)
);

